// Récupérer 3-5 news IA/n8n de la semaine pour contexte (optionnel)
// Si ça échoue, on continue sans
const feeds = [
  'https://blog.n8n.io/rss/',
  'https://www.anthropic.com/news/rss.xml',
  'https://openai.com/blog/rss.xml'
];
return feeds.map(url => ({ json: { url, case: $('Choisir un cas').first().json } }));

const now = Date.now();
const SEVEN_DAYS = 7 * 24 * 60 * 60 * 1000;
const items = $input.all();
const news = [];
for (const i of items) {
  const d = i.json;
  const pub = new Date(d.pubDate || d.isoDate || 0);
  if (now - pub.getTime() > SEVEN_DAYS) continue;
  news.push({ title: d.title, link: d.link, desc: (d.contentSnippet || '').slice(0, 300) });
  if (news.length >= 5) break;
}
return [{ json: { news, case: $('Choisir un cas').first().json } }];

