const resp = $input.first().json;
const raw = resp.content?.[0]?.text || '{}';
const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?$/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = { error: 'JSON invalide', raw: cleaned };
}

const caseData = $('Choisir un cas').first().json;
const today = new Date().toLocaleDateString('fr-FR', { day: '2-digit', month: 'long', year: 'numeric' });

const renderVariant = (label, color, goal, data) => {
  if (!data || !data.post) return '';
  return `
    <div style="background:#f9f9f9;border-left:5px solid ${color};padding:20px;margin:24px 0;border-radius:8px;">
      <div style="font-size:10px;color:${color};font-weight:700;text-transform:uppercase;letter-spacing:1.5px;">${label}</div>
      <div style="font-size:13px;color:#555;margin-top:4px;font-weight:600;">🎯 Objectif : ${goal}</div>
      <div style="font-size:12px;color:#888;margin-top:4px;font-style:italic;">Angle : ${data.angle || ''}</div>
      <div style="background:white;padding:20px;margin-top:14px;border:1px solid #eee;border-radius:6px;white-space:pre-wrap;font-family:-apple-system,'Segoe UI',sans-serif;font-size:14px;line-height:1.65;color:#222;">${(data.post || '').replace(/\n/g, '<br>')}</div>
    </div>
  `;
};

const html = `<!DOCTYPE html>
<html><head><meta charset="UTF-8"></head>
<body style="font-family:-apple-system,'Segoe UI',sans-serif;max-width:800px;margin:0 auto;padding:28px;color:#222;background:#fff;">
  <h1 style="color:#0a0a0a;border-bottom:3px solid #ff6b35;padding-bottom:12px;margin-bottom:6px;">3 brouillons LinkedIn AEF Solutions</h1>
  <p style="color:#666;font-size:13px;margin-top:0;">${today} · Cas exploité cette semaine</p>

  <div style="background:#fff4e6;border:1px solid #ffd4a3;padding:16px 20px;border-radius:8px;margin:20px 0;font-size:13px;">
    <strong style="color:#8b4513;">📂 Cas du jour :</strong> ${caseData.secteur}<br>
    <span style="color:#555;">Stack : ${caseData.stack}</span>
  </div>

  ${renderVariant('VARIANTE 1 — PROSPECTS', '#3b82f6', 'Attirer des PME qui se reconnaissent', parsed.variante_1_prospects)}
  ${renderVariant('VARIANTE 2 — EXPERTISE', '#8b5cf6', 'Positionnement technique auprès des pairs', parsed.variante_2_expert)}
  ${renderVariant('VARIANTE 3 — VENTE', '#10b981', 'Vendre une mission spécifique (CTA explicite)', parsed.variante_3_vente)}

  <div style="margin-top:36px;padding:20px;background:#fffbe6;border:1px solid #ffe58f;border-radius:8px;">
    <strong>🎯 À faire :</strong>
    <ol style="margin:10px 0 0 0;line-height:1.7;">
      <li>Choisis la variante qui correspond à ton objectif du moment</li>
      <li>Copie-colle dans LinkedIn (profil perso ou page AEF Solutions)</li>
      <li>Ajuste si besoin (spécifique ton ressenti) + publie</li>
    </ol>
  </div>

  <div style="margin-top:28px;padding-top:18px;border-top:1px solid #eee;color:#999;font-size:11px;">Généré automatiquement · rotation 8 semaines par cas · ${today}</div>
</body></html>`;

return [{ json: { html, date: today, case_id: caseData.id, parsed } }];
